  let result: MatchResult;
  try {
    result = await findOrCreateMatch(this.userId);
  } catch {
    this.isMatchmaking = false;
    this.showMenu();
    return;
  }

  if (result.status === 'matched') {
    this.onRankedMatchFound(result);
    return;
  }

