      fontSize: '14px',
      color: '#ff6666',
      fontStyle: 'bold',
      stroke: '#000000',
      strokeThickness: 3,
    }).setOrigin(1, 0).setDepth(10);

    // 생존 타이머 (100ms 주기)
    this.survivalTimerEvent = this.time.addEvent({
      delay: 100,
      callback: () => {
        if (!this.gameOver) {
          this.survivalMs += 100;
          if (this.survivalText?.active) {
