    this.survivalTimerEvent = this.time.addEvent({
      delay: 100,
      callback: () => {
        if (!this.gameOver) {
          this.survivalMs += 100;
          if (this.survivalText?.active) {
            this.survivalText.setText(`⏱ ${formatSurvivalTime(this.survivalMs)}`);
          }
