        if (this.channelReady && this.battleChannel) {
          this.battleChannel.sendScoreUpdate(this.survivalMs);
        }
        this.endBattle(BattleResult.WIN);
      }
    });

    // 상대 이탈 → 5초 대기 후 부전승
    this.battleChannel.onPresenceLeave(() => {
      if (!this.battleFinished && !this.gameOver) {
